def detect_cycle(head):
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False
This function uses Floyd's Tortoise and Hare algorithm to detect a cycle in the linked list. It iterates through the list with two pointers moving at different speeds. If a cycle exists, the slow pointer and fast pointer will eventually meet.

def detect_cycle(head):
    def helper(node, visited):
        if not node:
            return False
        if node in visited:
            return True
        visited.add(node)
        return helper(node.next, visited)
    return helper(head, set())

